mapper.select:


    inner join sys_user u on u.user_name = inspectionplandetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    inspectionplandetail.del_flag = '0'
     and inspectionplandetail.plan_id = #{planId}
     and inspectionplandetail.equipment_id = #{equipmentId}


${params.dataScope}
